package versioncheck

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/internal/entireclient/userdirs"
	"golang.org/x/mod/module"
	"golang.org/x/mod/semver"
)

const goosWindows = "windows"

// goos is a test seam for runtime.GOOS so the Windows-specific auto-install
// gating can be exercised from a non-Windows host.
var goos = runtime.GOOS

const (
	installManagerBrew    = "brew"
	installManagerMise    = "mise"
	installManagerScoop   = "scoop"
	installManagerUnknown = "unknown"
	installChannelStable  = "stable"
	installChannelNightly = "nightly"
)

// CheckAndNotify performs a version check and notifies the user if a newer version is available.
// This is the main entry point for the version check system.
// The function is silent on all errors to avoid interrupting CLI operations.
func CheckAndNotify(ctx context.Context, w io.Writer, currentVersion string) {
	// Skip checks for local/unreleased builds.
	if isDevBuild(currentVersion) {
		return
	}

	// Ensure the global config directory exists
	if err := ensureGlobalConfigDir(); err != nil {
		// Silent failure - don't block CLI operations
		return
	}

	// Load the cache to check when we last fetched
	cache, err := loadCache()
	if err != nil {
		cache = &VersionCache{}
	}

	// Skip if we checked recently (within 24 hours)
	if time.Since(cache.LastCheckTime) < checkInterval {
		return
	}

	// Fetch the latest version from the appropriate channel
	var latestVersion string
	if isNightly(currentVersion) {
		latestVersion, err = fetchLatestNightlyVersion(ctx)
	} else {
		latestVersion, err = fetchLatestVersion(ctx)
	}

	// Always update cache to avoid retrying on every CLI invocation
	cache.LastCheckTime = time.Now()
	if saveErr := saveCache(cache); saveErr != nil {
		logging.Debug(ctx, "version check: failed to save cache",
			"error", saveErr.Error())
	}

	if err != nil {
		logging.Debug(ctx, "version check: failed to fetch latest version",
			"error", err.Error())
		return
	}

	// Show notification and offer an interactive upgrade when outdated
	if isOutdated(currentVersion, latestVersion) {
		if cache.SkippedVersion == versionCacheKey(latestVersion) {
			return
		}

		action := MaybeAutoUpdate(ctx, w, currentVersion, latestVersion)
		if action == autoUpdateActionSkipUntilNextVersion {
			cache.SkippedVersion = versionCacheKey(latestVersion)
			if saveErr := saveCache(cache); saveErr != nil {
				logging.Debug(ctx, "version check: failed to save skipped version",
					"error", saveErr.Error())
			}
		}
	}
}

// globalConfigDirPath returns the CLI's global config directory. Resolution
// lives in userdirs.Config — the single implementation shared by all
// config-dir consumers (contexts.json, the file token store, this cache).
func globalConfigDirPath() string {
	return userdirs.Config()
}

// ensureGlobalConfigDir creates the global config directory if it doesn't exist.
func ensureGlobalConfigDir() error {
	//nolint:gosec // ~/.config/entire is user home directory, 0o755 is appropriate
	if err := os.MkdirAll(globalConfigDirPath(), 0o755); err != nil {
		return fmt.Errorf("creating config directory: %w", err)
	}

	return nil
}

// cacheFilePath returns the full path to the version check cache file.
func cacheFilePath() string {
	return filepath.Join(globalConfigDirPath(), cacheFileName)
}

// loadCache loads the version check cache from disk.
// Returns an error if the file doesn't exist or is corrupted.
func loadCache() (*VersionCache, error) {
	data, err := os.ReadFile(cacheFilePath())
	if err != nil {
		return nil, fmt.Errorf("reading cache file: %w", err)
	}

	var cache VersionCache
	if err := json.Unmarshal(data, &cache); err != nil {
		return nil, fmt.Errorf("parsing cache: %w", err)
	}

	return &cache, nil
}

// saveCache saves the version check cache to disk.
// Uses atomic write semantics (write to temp file, then rename).
func saveCache(cache *VersionCache) error {
	filePath := cacheFilePath()

	// Marshal to JSON
	data, err := json.MarshalIndent(cache, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling cache: %w", err)
	}

	// Write to temp file first (atomic write)
	dir := filepath.Dir(filePath)
	tmpFile, err := os.CreateTemp(dir, ".version_check_tmp_")
	if err != nil {
		return fmt.Errorf("creating temp file: %w", err)
	}
	defer os.Remove(tmpFile.Name())

	if _, err := tmpFile.Write(data); err != nil {
		_ = tmpFile.Close() // cleanup on error path
		return fmt.Errorf("writing cache: %w", err)
	}

	if err := tmpFile.Close(); err != nil {
		return fmt.Errorf("closing temp file: %w", err)
	}

	// Rename temp file to final location

	if err := os.Rename(tmpFile.Name(), filePath); err != nil {
		return fmt.Errorf("renaming cache file: %w", err)
	}

	return nil
}

// fetchLatestVersion fetches the latest stable version tag from the GitHub API.
func fetchLatestVersion(ctx context.Context) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, httpTimeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubAPIURL, nil)
	if err != nil {
		return "", fmt.Errorf("creating request: %w", err)
	}

	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", versioninfo.UserAgent())

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetching release info: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return "", fmt.Errorf("reading response: %w", err)
	}

	version, err := parseGitHubRelease(body)
	if err != nil {
		return "", fmt.Errorf("parsing release: %w", err)
	}
	return version, nil
}

// isNightly returns true if the version string is a nightly build.
func isNightly(version string) bool {
	if !strings.HasPrefix(version, "v") {
		version = "v" + version
	}
	return strings.Contains(semver.Prerelease(version), "nightly")
}

// fetchLatestNightlyVersion fetches the latest nightly version tag from the GitHub releases list.
func fetchLatestNightlyVersion(ctx context.Context) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, httpTimeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubReleasesURL+"?per_page=20", nil)
	if err != nil {
		return "", fmt.Errorf("creating request: %w", err)
	}

	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", versioninfo.UserAgent())

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetching releases: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return "", fmt.Errorf("reading response: %w", err)
	}

	var releases []GitHubRelease
	if err := json.Unmarshal(body, &releases); err != nil {
		return "", fmt.Errorf("parsing JSON: %w", err)
	}

	for _, r := range releases {
		if r.Prerelease && strings.Contains(r.TagName, "-nightly.") {
			return r.TagName, nil
		}
	}

	return "", errors.New("no nightly release found")
}

// parseGitHubRelease parses the GitHub API response and returns the latest stable version tag.
// Filters out prerelease versions.
func parseGitHubRelease(body []byte) (string, error) {
	var release GitHubRelease
	if err := json.Unmarshal(body, &release); err != nil {
		return "", fmt.Errorf("parsing JSON: %w", err)
	}

	if release.Prerelease {
		return "", errors.New("only prerelease versions available")
	}

	if release.TagName == "" {
		return "", errors.New("empty tag name")
	}

	return release.TagName, nil
}

// isOutdated compares current and latest versions using semantic versioning.
// Returns true if current < latest.
func isOutdated(current, latest string) bool {
	// Ensure versions have "v" prefix for semver package
	if !strings.HasPrefix(current, "v") {
		current = "v" + current
	}
	if !strings.HasPrefix(latest, "v") {
		latest = "v" + latest
	}

	// Local/unreleased builds shouldn't trigger update notifications.
	// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
	if isDevBuild(current) {
		return false
	}

	// semver.Compare returns -1 if current < latest
	return semver.Compare(current, latest) < 0
}

// isDevBuild reports whether v identifies a local, unreleased build that
// should not be nagged to update. This covers the "dev" sentinel and empty
// string (an unstamped binary), a Go pseudo-version (built from a commit that
// isn't a tagged release), and any build carrying +metadata such as "+dirty".
// Released builds — stable tags, nightly tags, and `go install ...@<tag>` —
// have clean semver and return false.
func isDevBuild(v string) bool {
	if v == "" || v == "dev" {
		return true
	}
	if !strings.HasPrefix(v, "v") {
		v = "v" + v
	}
	return !semver.IsValid(v) || module.IsPseudoVersion(v) || semver.Build(v) != ""
}

func versionCacheKey(version string) string {
	if version == "" || strings.HasPrefix(version, "v") {
		return version
	}
	return "v" + version
}

func displayVersion(version string) string {
	return strings.TrimPrefix(version, "v")
}

func releaseNotesURL(version string) string {
	return downloadsURL + "/tag/" + versionCacheKey(version)
}

// executablePath is the function used to get the current executable path.
// It's a variable so tests can override it.
var executablePath = os.Executable

func releaseChannel(version string) string {
	if isNightly(version) {
		return installChannelNightly
	}
	return installChannelStable
}

func installManagerForCurrentBinary() string {
	execPath, err := executablePath()
	if err != nil {
		return installManagerUnknown
	}

	realPath, err := filepath.EvalSymlinks(execPath)
	if err != nil {
		realPath = execPath
	}
	normalizedPath := strings.ReplaceAll(filepath.ToSlash(realPath), "\\", "/")

	switch {
	case strings.Contains(normalizedPath, "/Cellar/") ||
		strings.Contains(normalizedPath, "/opt/homebrew/") ||
		strings.Contains(normalizedPath, "/linuxbrew/") ||
		strings.Contains(normalizedPath, "/Caskroom/"):
		return installManagerBrew
	case strings.Contains(normalizedPath, "/mise/installs/"):
		return installManagerMise
	case strings.Contains(normalizedPath, "/scoop/apps/"):
		return installManagerScoop
	default:
		return installManagerUnknown
	}
}

// canAutoInstall reports whether updateCommand(currentVersion) is safe to
// execute on the current OS. Returns false on Windows when the install
// manager is unknown, because the POSIX curl-pipe-bash fallback can't run
// from cmd.exe and there's no Windows-native installer to substitute.
func canAutoInstall() bool {
	if goos != goosWindows {
		return true
	}
	switch installManagerForCurrentBinary() {
	case installManagerScoop, installManagerMise:
		return true
	default:
		return false
	}
}

// downloadsURL is the public page users visit when we can't offer an
// auto-installable command on their platform.
const downloadsURL = "https://github.com/entireio/cli/releases"

// updateCommand returns the appropriate update instruction based on how the binary was installed.
func updateCommand(currentVersion string) string {
	switch installManagerForCurrentBinary() {
	case installManagerBrew:
		if releaseChannel(currentVersion) == installChannelNightly {
			return "brew upgrade --yes entire@nightly"
		}
		return "brew upgrade --yes entire"
	case installManagerMise:
		return "mise upgrade entire"
	case installManagerScoop:
		return "scoop update entire/cli"
	}

	if releaseChannel(currentVersion) == installChannelNightly {
		return "curl -fsSL https://entire.io/install.sh | bash -s -- --channel nightly"
	}
	return "curl -fsSL https://entire.io/install.sh | bash"
}

func UpdateCommandForCurrentBinary(currentVersion string) string {
	if !canAutoInstall() {
		return downloadsURL
	}
	return updateCommand(currentVersion)
}

// printNotification prints the version update notification to the user.
func printNotification(w io.Writer, current, latest string) {
	fmt.Fprintf(w, "\nUpdate available! %s -> %s\nRelease notes: %s\n",
		displayVersion(current), displayVersion(latest), releaseNotesURL(latest))
}

			}
		}

		// Load settings once for telemetry and version check
		var telemetryEnabled *bool
		settings, err := LoadEntireSettings(cmd.Context())
		if err == nil {
			telemetryEnabled = settings.Telemetry
		}

		// Check if telemetry is enabled
		if telemetryEnabled != nil && *telemetryEnabled {
			// Use detached tracking (non-blocking)
			installedAgents := GetAgentsWithHooksInstalled(cmd.Context())
			agentStr := JoinAgentNames(installedAgents)
			telemetry.TrackCommandDetached(cmd, agentStr, settings.Enabled, versioninfo.Version)
		}

		// Version check and notification (synchronous with 2s timeout)
		// Runs AFTER command completes to avoid interfering with interactive modes.
		// Stderr, never stdout: this hook also fires after --json commands whose
		// stdout is piped into jq or captured by scripts — a notice on stdout
		// corrupts that output while staying invisible in the caller's logs.
		versioncheck.CheckAndNotify(cmd.Context(), cmd.ErrOrStderr(), versioninfo.Version)
	},
	RunE: func(cmd *cobra.Command, _ []string) error {
		ctx := cmd.Context()
		// If we're in a git repo but Entire isn't set up yet, start the setup flow
		if _, err := paths.WorktreeRoot(ctx); err == nil && !settings.IsSetUpAny(ctx) {
			return runSetupFlow(ctx, cmd.OutOrStdout(), EnableOptions{})
		}
		return cmd.Help()
	},
}

// Help groups; AddGroup order is display order in `entire --help`.
cmd.AddGroup(
	&cobra.Group{ID: groupSetup, Title: "Entire Setup:"},
	&cobra.Group{ID: groupSessions, Title: "Sessions & Checkpoints:"},
	&cobra.Group{ID: groupAccount, Title: "Account:"},
	&cobra.Group{ID: groupControlPlane, Title: "Control Plane:"},
)

// Noun groups (canonical homes for subcommands).
cmd.AddCommand(inGroup(newSessionsCmd(), groupSessions))        // 'session' (with 'sessions' as Cobra alias)
cmd.AddCommand(inGroup(newCheckpointGroupCmd(), groupSessions)) // 'checkpoint' / 'cp' / 'checkpoints'
experimental.Register(cmd, newTokensGroupCmd())                 // 'tokens' (experimental)
cmd.AddCommand(inGroup(newAgentGroupCmd(), groupSetup))         // 'agent'
cmd.AddCommand(inGroup(newAuthCmd(), groupAccount))             // 'auth'
cmd.AddCommand(inGroup(newDoctorCmd(), groupSetup))             // 'doctor' (group: trace/logs/bundle)

package auth

import (
	"context"
	"errors"
	"net/http"
	"strings"
	"time"

	"github.com/entireio/auth-go/authcode"
	"github.com/entireio/auth-go/deviceflow"
	"github.com/entireio/auth-go/tokens"
	"github.com/entireio/cli/cmd/entire/cli/api"
)

// nowFunc is the package's clock. Override in tests.
var nowFunc = time.Now

// DeviceAuthStart preserves the historical type name; the shape now
// matches deviceflow.DeviceCode field-for-field.
type DeviceAuthStart = deviceflow.DeviceCode

// DeviceAuthPoll is the historical token-poll response shape. The shim
// flattens deviceflow's typed errors back into the Error field so
// existing login.go logic that switches on result.Error keeps working.
//
// ErrorDescription carries the optional `error_description` from the
// server's RFC 8628 §3.5 error response, when present. Used to give
// callers a more actionable message than the bare error code.
type DeviceAuthPoll struct {
	AccessToken      string
	RefreshToken     string
	TokenType        string
	ExpiresIn        int
	Scope            string
	Error            string
	ErrorDescription string
}

// Client wraps a deviceflow.Client and an authcode.Client preconfigured
// for the entire-cli public client (see provider.go for the endpoint
// wiring).
type Client struct {
	inner   *deviceflow.Client
	browser *authcode.Client
}

// NewClient constructs a Client for the device-flow login against server
// (the login-server origin, validated by the caller — `entire login
// --server`). httpClient.Transport is reused when non-nil (its TLS /
// proxy config flows through); a nil httpClient or nil Transport falls
// back to the deviceflow default (http.DefaultTransport).
//
// HTTPS is required by default. Loopback http:// (localhost, 127.0.0.1,
// ::1) is always permitted — see isLoopbackHTTP. allowInsecureHTTP=true
// additionally permits non-loopback http:// for cases like local-dev
// auth hosts on a private network (e.g. http://devbox.internal); the
// CLI plumbs this from the --insecure-http-auth flag.
func NewClient(server string, httpClient *http.Client, allowInsecureHTTP bool) *Client {
	issuer := api.NormalizeOriginURL(server)
	var transport http.RoundTripper
	if httpClient != nil {
		transport = httpClient.Transport
	}
	// offline_access asks the authorization server for a refresh token.
	// The server only mints one when it's requested (it's client-gated),
	// so without this the login is access-token-only and silent refresh is
	// impossible. Both flows request it identically.
	const scope = "cli offline_access"
	allowHTTP := allowInsecureHTTP || isLoopbackHTTP(issuer)
	return &Client{
		inner: &deviceflow.Client{
			Transport:         transport,
			BaseURL:           issuer,
			ClientID:          oauthClientID,
			Scope:             scope,
			UserAgent:         oauthClientID,
			DeviceCodePath:    oauthDeviceCodePath,
			TokenPath:         oauthTokenPath,
			AllowInsecureHTTP: allowHTTP,
		},
		browser: &authcode.Client{
			Transport:         transport,
			BaseURL:           issuer,
			ClientID:          oauthClientID,
			Scope:             scope,
			UserAgent:         oauthClientID,
			AuthorizePath:     oauthAuthorizePath,
			TokenPath:         oauthTokenPath,
			AllowInsecureHTTP: allowHTTP,
		},
	}
}

// BrowserAuthFlow is one in-progress loopback authorization-code login. It
// wraps an authcode.Flow, flattening the TokenSet to the (access, refresh)
// pair login.go persists — mirroring how PollDeviceAuth flattens the
// device-flow result. login.go depends on a small local interface that this
// concrete type satisfies, so it can fake the flow in tests.
type BrowserAuthFlow struct {
	inner *authcode.Flow
}

// AuthorizationURL is the URL to open in the user's browser.
func (f *BrowserAuthFlow) AuthorizationURL() string { return f.inner.AuthorizationURL }

// Wait blocks until the browser is redirected to the loopback listener,
// returning the authorization code.
func (f *BrowserAuthFlow) Wait(ctx context.Context) (string, error) {
	return f.inner.Wait(ctx) //nolint:wrapcheck // shim preserves the lib's wrapped errors verbatim for errors.Is
}

// Exchange redeems code for access + refresh tokens.
func (f *BrowserAuthFlow) Exchange(ctx context.Context, code string) (accessToken, refreshToken string, err error) {
	ts, err := f.inner.Exchange(ctx, code)
	if err != nil {
		return "", "", err //nolint:wrapcheck // shim returns authcode errors verbatim so callers can errors.Is on sentinels
	}
	return ts.AccessToken, ts.RefreshToken, nil
}

// Close tears down the loopback listener. Safe to call after Wait.
func (f *BrowserAuthFlow) Close() error {
	return f.inner.Close() //nolint:wrapcheck // shutdown error is best-effort; caller logs at most
}

// StartBrowserAuth begins the loopback authorization-code flow: it binds a
// local listener and returns a flow carrying the browser URL to open.
func (c *Client) StartBrowserAuth(ctx context.Context) (*BrowserAuthFlow, error) {
	f, err := c.browser.Start(ctx)
	if err != nil {
		return nil, err //nolint:wrapcheck // shim returns authcode errors verbatim so callers can errors.Is on sentinels
	}
	return &BrowserAuthFlow{inner: f}, nil
}

// BaseURL returns the issuer base URL this client talks to.
func (c *Client) BaseURL() string { return c.inner.BaseURL }

// StartDeviceAuth requests a fresh device code.
func (c *Client) StartDeviceAuth(ctx context.Context) (*DeviceAuthStart, error) {
	return c.inner.StartDeviceAuth(ctx) //nolint:wrapcheck // shim preserves the lib's wrapped errors verbatim
}

// PollDeviceAuth polls the token endpoint. On any OAuth-protocol error
// (recognised RFC 8628 §3.5 sentinel or unknown but spec-shaped code
// like invalid_request / invalid_client / server_error), the wire-side
// code is returned in DeviceAuthPoll.Error so the existing polling
// loop in login.go can branch on it — known codes hit the dedicated
// switch arms, unknown codes fall through to the default arm and fail
// fast. Non-protocol errors (network, decode) are returned as a real
// error and treated as transient by the polling loop.
func (c *Client) PollDeviceAuth(ctx context.Context, deviceCode string) (*DeviceAuthPoll, error) {
	t, err := c.inner.PollDeviceAuth(ctx, deviceCode)
	if err != nil {
		if code, description, ok := oauthErrorParts(err); ok {
			return &DeviceAuthPoll{
				Error:            code,
				ErrorDescription: description,
			}, nil
		}
		return nil, err //nolint:wrapcheck // shim returns deviceflow errors verbatim so callers can errors.Is on sentinels
	}

	return &DeviceAuthPoll{
		AccessToken:  t.AccessToken,
		RefreshToken: t.RefreshToken,
		TokenType:    t.TokenType,
		ExpiresIn:    secondsUntil(t),
		Scope:        t.Scope,
	}, nil
}

// oauthErrorParts inspects err for either a recognised RFC 8628 §3.5
// sentinel or the generic "oauth error: <code>" wrapper deviceflow uses
// for unrecognised but spec-shaped codes (RFC 6749 §5.2: invalid_request,
// invalid_client, server_error, …).
//
// On a match, returns the wire-side code, any error_description the
// server included, and ok=true. Otherwise returns "", "", false — the
// caller should treat the error as a transport/decode failure.
//
// Surfacing unknown codes as ok=true is what keeps login.go's polling
// loop fast-failing on terminal OAuth rejections instead of treating
// them as transient and retrying ~5 times.
func oauthErrorParts(err error) (code, description string, ok bool) {
	switch {
	case errors.Is(err, deviceflow.ErrAuthorizationPending):
		code = "authorization_pending"
	case errors.Is(err, deviceflow.ErrSlowDown):
		code = "slow_down"
	case errors.Is(err, deviceflow.ErrAccessDenied):
		code = "access_denied"
	case errors.Is(err, deviceflow.ErrExpiredToken):
		code = "expired_token"
	case errors.Is(err, deviceflow.ErrInvalidGrant):
		code = "invalid_grant"
	default:
		// Unknown but legitimate OAuth codes come back from
		// deviceflow.errCodeToSentinel as fmt.Errorf("oauth error: %s",
		// code), optionally wrapped a second time with ": <description>"
		// when the server supplied error_description.
		const oauthPrefix = "oauth error: "
		rest, hadPrefix := strings.CutPrefix(err.Error(), oauthPrefix)
		if !hadPrefix {
			return "", "", false
		}
		if c, d, hasDesc := strings.Cut(rest, ": "); hasDesc {
			return c, d, true
		}
		return rest, "", true
	}
	description = descriptionFromSentinelError(err, code)
	return code, description, true
}

// descriptionFromSentinelError pulls the description suffix out of a
// wrapped sentinel error. The deviceflow lib uses
// fmt.Errorf("%w: %s", sentinel, description) when the server included
// an error_description, so the formatted error reads
// "<code>: <description>". Stripping the "<code>: " prefix yields the
// description; absent prefix means the server didn't supply one.
func descriptionFromSentinelError(err error, code string) string {
	msg := err.Error()
	prefix := code + ": "
	if rest, ok := strings.CutPrefix(msg, prefix); ok {
		return rest
	}
	return ""
}

// secondsUntil computes seconds-until-expiry for a TokenSet with an
// absolute ExpiresAt. Returns 0 when no expiry is set or when ExpiresAt
// is already in the past (clock skew, scheduling delays) — ExpiresIn is
// contractually non-negative; downstream loggers and display code don't
// expect a negative value.
func secondsUntil(t *tokens.TokenSet) int {
	if t.ExpiresAt.IsZero() {
		return 0
	}
	return max(0, int(t.ExpiresAt.Unix()-nowFunc().Unix()))
}

