3	// SilentError wraps an error to signal that the error message has already been
4	// printed to the user. main.go checks for this type to avoid duplicate output.
5	type SilentError struct {
6		Err error
7	}
8	
9	func (e *SilentError) Error() string {
10		return e.Err.Error()
11	}
12	
13	func (e *SilentError) Unwrap() error {
14		return e.Err
15	}
